  void RefreshLibrarySession(){if(session==null){sessionText.Text="";sessionActions.Visibility=Visibility.Collapsed;return;}TimeSpan remaining=TimeSpan.FromSeconds(Math.Ceiling(session.Remaining.TotalSeconds));sessionText.Text=session.Started?"Sessão em andamento · "+FormatRemaining(remaining)+" restantes":"Tempo de prática selecionado: "+session.Duration.TotalMinutes.ToString("0")+" minutos";resumeButton.Visibility=session.Activity==null?Visibility.Collapsed:Visibility.Visible;sessionActions.Visibility=session.Activity!=null||session.Started?Visibility.Visible:Visibility.Collapsed;}
