  void Render()
  {
   if(repo==null||query==null)return;
   List<Activity> matches=repo.Find(query.Text,difficulty,selectedCategoryId);string categoryName=selectedCategoryId==null?null:repo.Categories.First(c=>c.Id==selectedCategoryId).Name;
   libraryTitle.Text=categoryName??"Biblioteca educativa";libraryDescription.Text=selectedCategoryId==null?"Descubra coisas incríveis enquanto pratica digitação":repo.Categories.First(c=>c.Id==selectedCategoryId).Description;
   libraryCounts.Text=selectedCategoryId==null?repo.Categories.Count+" categorias • "+repo.Activities.Count+" atividades no catálogo":matches.Count+" de "+repo.Activities.Count(x=>x.CategoryId==selectedCategoryId)+" atividades";if(bannerArt!=null){string artPath=selectedCategoryId==null?Path.Combine(root,Path.Combine("Assets","mascote-ensinando.png")):Path.Combine(Path.Combine(root,Path.Combine("Assets","Categorias")),selectedCategoryId+".png");if(File.Exists(artPath))bannerArt.Source=new BitmapImage(new Uri(artPath));}
