   if(!showActivities){foreach(Category category in repo.Categories){int count=repo.Find(query.Text,difficulty,category.Id).Count;if(count==0)continue;Button card=LegacyControls.Button("",delegate{selectedCategoryId=category.Id;Render();},false);card.Width=205;card.MinHeight=190;card.Padding=new Thickness(10);card.HorizontalContentAlignment=HorizontalAlignment.Stretch;System.Windows.Automation.AutomationProperties.SetName(card,category.Name);StackPanel body=new StackPanel();Border artTile=new Border{Background=(Brush)new BrushConverter().ConvertFromString(category.Color),CornerRadius=new CornerRadius(9),Margin=new Thickness(0,0,0,9)};Image art=Pic("Assets/Categorias/"+category.Id+".png",74);art.HorizontalAlignment=HorizontalAlignment.Center;artTile.Child=art;body.Children.Add(artTile);body.Children.Add(T(category.Name,16,true));body.Children.Add(T(category.Description,12,false,new SolidColorBrush(Color.FromRgb(84,92,105))));body.Children.Add(T(count+(count==1?" atividade  →":" atividades  →"),12,true,Red));card.Content=body;categoryCards.Children.Add(card);}}
