  void ChooseRandom(){List<Activity> matches=repo.Find(query==null?"":query.Text,difficulty,selectedCategoryId);if(matches.Count==0)return;List<Activity> candidates=matches.Where(a=>session==null||a.Id!=session.LastCompletedId).ToList();if(candidates.Count==0)candidates=matches;OpenActivity(candidates[new Random().Next(candidates.Count)]);}
  void OpenActivity(Activity activity){if(session==null||session.Finished){session=new SessionManager(durationMinutes,new SessionClock());resultsVisible=false;}if(session.Open(activity))Practice();else Results();}
