   SizeChangedEventHandler resizeEditor=delegate{
    bool stacked=editor.ActualWidth<550;
    bool compact=pageScroll.ActualHeight<490||editor.ActualWidth<800;
    int columns=stacked?1:2;
    if(editor.ColumnDefinitions.Count!=columns){
     editor.ColumnDefinitions.Clear();editor.RowDefinitions.Clear();
     editor.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(2,GridUnitType.Star)});
     if(stacked){
      editor.RowDefinitions.Add(new RowDefinition());
      editor.RowDefinitions.Add(new RowDefinition());
     }else editor.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(3,GridUnitType.Star)});
     Grid.SetRow(inputCard,stacked?1:0);Grid.SetColumn(inputCard,stacked?0:1);
    }
    heading.Padding=new Thickness(compact?6:20);
    heading.Margin=new Thickness(0,0,0,compact?3:12);
    toolbar.Margin=new Thickness(0,0,0,compact?2:8);
    referenceCard.Padding=inputCard.Padding=new Thickness(compact?7:14);
    referenceCard.Margin=inputCard.Margin=new Thickness(compact?2:4);
    metricCards.Columns=editor.ActualWidth<440?2:4;
    metricCards.Margin=new Thickness(-5,compact?2:6,-5,compact?0:4);
    foreach(Border metric in metricCards.Children){
     metric.Padding=new Thickness(compact?5:12);
     metric.Margin=new Thickness(compact?3:5);
     StackPanel contents=(StackPanel)metric.Child;
     foreach(TextBlock text in contents.Children)text.Margin=new Thickness(6,compact?1:6,6,compact?1:6);
    }
    foreach(Button button in toolbar.Children.OfType<Button>().Concat(controls.Children.OfType<Button>())){
     button.Padding=compact?new Thickness(10,5,10,5):new Thickness(14,9,14,9);
     button.Margin=new Thickness(compact?3:5);
    }
    // Keep a usable editor when the outer page needs to scroll on a very small viewport.
    double available=pageScroll.ActualHeight-page.Margin.Top-page.Margin.Bottom-editorHeader.ActualHeight-editorFooter.ActualHeight;
    editor.Height=Math.Max(stacked?244:142,available);
   };
   editorHeader.SizeChanged+=resizeEditor;editorFooter.SizeChanged+=resizeEditor;editor.SizeChanged+=resizeEditor;
   editor.Loaded+=delegate{pageScroll.SizeChanged+=resizeEditor;resizeEditor(editor,null);};
   editor.Unloaded+=delegate{pageScroll.SizeChanged-=resizeEditor;};
