  void UpdatePracticeWarning(){if(warningText==null||session==null)return;TimeSpan remaining=TimeSpan.FromSeconds(Math.Ceiling(session.Remaining.TotalSeconds));warningText.Text=!session.Started?"O tempo começa quando você digitar.":remaining.TotalSeconds<=60?"Último minuto de prática.":remaining.TotalMinutes<=5?"Restam até cinco minutos de prática.":"";warningText.Visibility=string.IsNullOrEmpty(warningText.Text)||preferences.Concentration?Visibility.Collapsed:Visibility.Visible;}
  void ChangeEditorFont(int delta){preferences.FontPoints=Math.Max(12,Math.Min(28,preferences.FontPoints+delta));double size=preferences.FontPoints*96.0/72.0;if(entry!=null)entry.FontSize=size;if(referenceBlock!=null){referenceBlock.FontSize=size;referenceBlock.LineHeight=size*1.45;}if(fontValue!=null)fontValue.Text=preferences.FontPoints+" pt";}
