  void ApplyPracticePreferences(){if(activeMetricCards!=null)activeMetricCards.Visibility=preferences.ShowMetrics&&(!preferences.Concentration||!preferences.HideMetricsInConcentration)?Visibility.Visible:Visibility.Collapsed;if(concentrationToolbarButton!=null)concentrationToolbarButton.Content=preferences.Concentration?"Sair da concentração":"Concentração";if(navigationBar!=null)navigationBar.Visibility=inPractice&&preferences.Concentration?Visibility.Collapsed:Visibility.Visible;}
  void SavePreferences(){try{preferences.Save(preferencesPath);}catch(Exception ex){MessageBox.Show("Não foi possível salvar as preferências.\n"+ex.Message,"IT Digitação",MessageBoxButton.OK,MessageBoxImage.Error);}}
  void UpdateReferenceFeedback(){if(session==null||session.Engine==null||referenceRuns==null)return;TypingEngine engine=session.Engine;for(int i=0;i<referenceRuns.Length;i++){Run run=referenceRuns[i];run.Foreground=!preferences.VisualFeedback||i>=engine.Entered?Ink:(engine.IsCorrectAt(i)?Correct:Error);run.ClearValue(TextElement.BackgroundProperty);run.ClearValue(Inline.TextDecorationsProperty);if(preferences.VisualFeedback&&i<engine.Entered&&!engine.IsCorrectAt(i))run.TextDecorations=TextDecorations.Underline;if(preferences.VisualFeedback&&i==engine.Entered)run.Background=Next;}}
  void UpdatePracticeMetrics(Panel cards,ProgressBar bar){if(session==null||session.Engine==null||cards.Children.Count<4)return;string[] values={(session.WordsPerMinute.HasValue?session.WordsPerMinute.Value.ToString("0.#"):"—"),(session.Accuracy.HasValue?session.Accuracy.Value.ToString("0.#")+"%":"—"),session.TotalErrors.ToString(),session.CurrentErrors.ToString()};for(int i=0;i<4;i++){StackPanel content=(StackPanel)((Border)cards.Children[i]).Child;((TextBlock)content.Children[1]).Text=values[i];}stats.Text="Precisão "+(session.Accuracy.HasValue?session.Accuracy.Value.ToString("0.#")+"%":"—")+"  ·  PPM "+(session.WordsPerMinute.HasValue?session.WordsPerMinute.Value.ToString("0.#"):"—")+"  ·  Erros cometidos "+session.TotalErrors+"  ·  Corrigidos "+session.CorrectedErrors+"  ·  No texto "+session.CurrentErrors+"\nProgresso do texto: "+(session.Engine.Complete?"100% · Texto pronto para concluir":(session.Engine.Progress>=100?"100% preenchido · remova o conteúdo excedente":Math.Floor(session.Engine.Progress).ToString("0")+"%"));bar.Value=session.Engine.Progress;}
  static string FormatRemaining(TimeSpan value){if(value<TimeSpan.Zero)value=TimeSpan.Zero;return string.Format("{0:00}:{1:00}",(int)Math.Floor(value.TotalMinutes),value.Seconds);}
