  void AddKeyboardRow(Panel parent,string[] labels,int[] fingers){WrapPanel row=new WrapPanel{HorizontalAlignment=HorizontalAlignment.Center,Margin=new Thickness(0,2,0,2)};for(int i=0;i<labels.Length;i++){string label=labels[i];Border key=new Border{Width=(label=="Backspace"||label=="Enter"?74:(label=="Espaço"?170:(label=="Caps"||label=="Shift"?58:38))),Height=37,Margin=new Thickness(2),Padding=new Thickness(2),CornerRadius=new CornerRadius(5),BorderThickness=new Thickness(1),BorderBrush=new SolidColorBrush(Color.FromRgb(112,117,126)),Background=fingerColors[fingers[i]],Tag=fingerColors[fingers[i]],ToolTip="Dedo: "+fingerNames[fingers[i]]};TextBlock text=T(label,11,true,Ink);text.HorizontalAlignment=HorizontalAlignment.Center;text.VerticalAlignment=VerticalAlignment.Center;key.Child=text;row.Children.Add(key);string id=KeyboardKeyId(label);if(!string.IsNullOrEmpty(id))keyboardKeys[id]=key;if(label=="F"||label=="J")key.BorderThickness=new Thickness(2);}parent.Children.Add(row);}
  static string KeyboardKeyId(string label){if(label.Length==0)return null;if(label.Length>1&&label[1]==' ')return label.Substring(0,1);switch(label){case "Espaço":return "SPACE";case "Backspace":return "BACKSPACE";case "Caps":return "CAPS";default:return label;}}
  void GuideKeyPressed(object sender,KeyEventArgs e){if(navGuide==null||navGuide.IsChecked!=true)return;string id=e.Key.ToString().ToUpperInvariant();if(id.Length==2&&id[0]=='D')id=id.Substring(1);switch(id){case "SPACE":id="SPACE";break;case "BACK":id="BACKSPACE";break;case "CAPITAL":id="CAPS";break;case "OEMSEMICOLON":id="Ç";break;case "OEMQUOTES":id="´";break;case "OEMOPENBRACKETS":id="[";break;case "OEMCLOSEBRACKETS":id="]";break;case "OEMCOMMA":id=",";break;case "OEMPERIOD":id=".";break;case "OEMQUESTION":id="/";break;case "OEMBACKSLASH":id="\\";break;case "OEMPLUS":id="=";break;case "OEMMINUS":id="-";break;}if(highlightedKey!=null){highlightedKey.Background=(Brush)highlightedKey.Tag;((TextBlock)highlightedKey.Child).Foreground=Ink;}Border key;if(keyboardKeys.TryGetValue(id,out key)){highlightedKey=key;key.Background=new SolidColorBrush(Color.FromRgb(255,215,0));((TextBlock)key.Child).Foreground=Ink;if(keyboardHint!=null)keyboardHint.Text=key.Child is TextBlock?((TextBlock)key.Child).Text+" — "+(string)key.ToolTip+". Procure as marcas em F e J.":(string)key.ToolTip;}}
  void Settings(){if(!settingsOpen){settingsFromPractice=inPractice;settingsReturnTab=inPractice?navLibrary:(lastNavigation??navHome);settingsOpen=true;}inPractice=false;SelectNavigation(navSettings);navigationBar.Visibility=Visibility.Visible;Reset("Configurações","Ajuste a leitura e a experiência de prática.");Border banner=new Border{Background=new LinearGradientBrush(Color.FromRgb(166,0,0),Color.FromRgb(217,0,0),45),CornerRadius=new CornerRadius(16),Padding=new Thickness(20),Margin=new Thickness(0,0,0,12)};Grid bannerGrid=new Grid();bannerGrid.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(3,GridUnitType.Star)});bannerGrid.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(1,GridUnitType.Star)});StackPanel bannerText=new StackPanel{VerticalAlignment=VerticalAlignment.Center};bannerText.Children.Add(T("Configurações",28,true,Brushes.White));bannerText.Children.Add(T("Ajuste a leitura e a experiência de prática.",14,false,Brushes.White));bannerGrid.Children.Add(bannerText);Image settingsMascot=Pic("Assets/mascote-ensinando.png",90);Grid.SetColumn(settingsMascot,1);bannerGrid.Children.Add(settingsMascot);banner.Child=bannerGrid;page.Children.Add(banner);Border appearance=SettingsCard("Aparência e leitura");StackPanel appearanceContent=(StackPanel)appearance.Child;appearanceContent.Children.Add(T("Tamanho da fonte",15,true));TextBlock fontLabel=T("Tamanho da fonte: "+preferences.FontPoints+" pt",14,false);appearanceContent.Children.Add(fontLabel);Slider font=new Slider{Minimum=12,Maximum=28,Value=preferences.FontPoints,MaxWidth=360,TickFrequency=1,IsSnapToTickEnabled=true};TextBlock preview=T("Aprender é transformar. Pratique no seu ritmo.",preferences.FontPoints*96.0/72.0,false);Border previewCard=new Border{Background=new SolidColorBrush(Color.FromRgb(255,241,242)),Padding=new Thickness(12),Child=preview};font.ValueChanged+=delegate{preview.FontSize=font.Value*96.0/72.0;fontLabel.Text="Tamanho da fonte: "+font.Value.ToString("0")+" pt";};appearanceContent.Children.Add(font);appearanceContent.Children.Add(previewCard);page.Children.Add(appearance);
   UniformGrid optionCards=new UniformGrid{Columns=2,Margin=new Thickness(-4,0,-4,0)};optionCards.SizeChanged+=delegate{optionCards.Columns=optionCards.ActualWidth>=610?2:1;};Border behavior=SettingsCard("Experiência de digitação");StackPanel behaviorContent=(StackPanel)behavior.Child;CheckBox sound=LegacyControls.PreferenceCheckBox("Som suave ao concluir um texto",preferences.Sounds);CheckBox metrics=LegacyControls.PreferenceCheckBox("Exibir métricas durante a prática",preferences.ShowMetrics);CheckBox focus=LegacyControls.PreferenceCheckBox("Modo concentração",preferences.Concentration);CheckBox hide=LegacyControls.PreferenceCheckBox("Ocultar métricas no modo concentração",preferences.HideMetricsInConcentration);CheckBox feedback=LegacyControls.PreferenceCheckBox("Mostrar acertos, erros e próximo caractere",preferences.VisualFeedback);behaviorContent.Children.Add(sound);behaviorContent.Children.Add(metrics);behaviorContent.Children.Add(focus);behaviorContent.Children.Add(hide);behaviorContent.Children.Add(feedback);optionCards.Children.Add(behavior);
   Border performance=SettingsCard("Desempenho");StackPanel performanceContent=(StackPanel)performance.Child;CheckBox animations=LegacyControls.PreferenceCheckBox("Animar a apresentação dos resultados",preferences.Animations);CheckBox effects=LegacyControls.PreferenceCheckBox("Reduzir efeitos visuais",preferences.ReducedEffects);performanceContent.Children.Add(animations);performanceContent.Children.Add(effects);optionCards.Children.Add(performance);page.Children.Add(optionCards);
   WrapPanel buttons=new WrapPanel{HorizontalAlignment=HorizontalAlignment.Center};buttons.Children.Add(B("Salvar preferências",delegate{preferences.FontPoints=(int)font.Value;preferences.Sounds=sound.IsChecked==true;preferences.ShowMetrics=metrics.IsChecked==true;preferences.Concentration=focus.IsChecked==true;preferences.HideMetricsInConcentration=hide.IsChecked==true;preferences.VisualFeedback=feedback.IsChecked==true;preferences.Animations=animations.IsChecked==true;preferences.ReducedEffects=effects.IsChecked==true;try{preferences.Save(preferencesPath);if(completionSound!=null){completionSound.Dispose();completionSound=null;}if(preferences.Sounds){string soundFile=Path.Combine(root,Path.Combine("Assets","conclusao.wav"));if(File.Exists(soundFile))completionSound=new SoundPlayer(soundFile);}ApplyPracticePreferences();if(entry!=null)ChangeEditorFont(0);MessageBox.Show("Preferências salvas neste usuário.","IT Digitação",MessageBoxButton.OK,MessageBoxImage.Information);ReturnFromSettings();}catch(Exception ex){MessageBox.Show("Não foi possível salvar as preferências.\n"+ex.Message,"IT Digitação",MessageBoxButton.OK,MessageBoxImage.Error);}},true));buttons.Children.Add(B("Restaurar padrões",delegate{preferences=new Preferences();Settings();},false));buttons.Children.Add(B(settingsFromPractice?"Retornar à digitação":"Retornar",ReturnFromSettings,false));page.Children.Add(buttons);}
  void ReturnFromSettings(){bool returnToPractice=settingsFromPractice&&session!=null&&session.Engine!=null&&!session.Finished;RadioButton target=settingsReturnTab;settingsOpen=false;settingsFromPractice=false;if(returnToPractice){Practice();return;}if(target==navLibrary)Library();else if(target==navGuide)Guide();else Home();}
